// Generates src/core/config_tpl.c from the reference implementation.
//
// makeConfig() emits large fixed ZPAQL postprocessor programs whose text
// depends only on (level, e8e9 flag, level-1 r-bits, level-3 block size
// class) plus the generated component list.  Instead of retyping those
// programs by hand, this tool asks upstream makeConfig for each variant and
// stores the exact text.  The component list is generated by config.c using
// the same rules as upstream.
//
// Usage: gen_config <upstream-dir> > src/core/config_tpl.c
#include "libzpaq.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <string>

namespace libzpaq {
std::string makeConfig(const char *method, int args[]);
}

void libzpaq::error(const char *msg) {
  fprintf(stderr, "gen_config: %s\n", msg);
  exit(1);
}

static void emit_str(const char *s) {
  fputc('"', stdout);
  for (; *s; ++s) {
    const unsigned char c = (unsigned char)*s;
    switch (c) {
      case '\\': fputs("\\\\", stdout); break;
      case '"': fputs("\\\"", stdout); break;
      case '\n': fputs("\\n", stdout); break;
      case '\t': fputs("\\t", stdout); break;
      default:
        if (c < 32 || c > 126) printf("\\x%02x", c);
        else fputc(c, stdout);
    }
  }
  fputc('"', stdout);
}

/* Return the tail of the config that belongs to the postprocessor: from
 * "\npcomp" to the end, or just "end\n" when the config has no pcomp. */
static std::string pcomp_part(const std::string &cfg) {
  const size_t p = cfg.find("\npcomp");
  if (p == std::string::npos) {
    /* level 0 without e8e9: the trailing "end\n" closes HCOMP */
    const size_t e = cfg.rfind("end\n");
    return e == std::string::npos ? std::string("end\n") : cfg.substr(e);
  }
  return cfg.substr(p + 1);
}

/* Fixed HCOMP prologue: text after the common first line, up to the first
 * "halt\n" (the HCOMP's own halt, before any postprocessor program). */
static std::string hcomp_part(const std::string &cfg) {
  static const char base[] = "hcomp\nc-- *c=a a+= 255 d=a *d=c\n";
  const size_t h = cfg.find(base);
  if (h == std::string::npos) return "";
  const size_t start = h + sizeof(base) - 1;
  const size_t end = cfg.find("halt\n", start);
  if (end == std::string::npos || end < start) return "";
  return cfg.substr(start, end - start);
}

static std::string gen(const std::string &method) {
  int args[9];
  memset(args, 0, sizeof(args));
  return libzpaq::makeConfig(method.c_str(), args);
}

static std::string with_blocksize(int level, int pre, const char *suffix) {
  char buf[128];
  const char *s = suffix;
  if (level == 1) {
    /* min match 5, no secondary match, 2^3 searches, 2^22 hash entries */
    snprintf(buf, sizeof(buf), "x%d.%d.5.0.3.22", 4, pre);
    s = buf;
  } else if (level == 2) {
    /* byte LZ77: min match 12, secondary 0, 2^7 searches, SA (25) */
    snprintf(buf, sizeof(buf), "x%d.%d.12.0.7.25.1", 4, pre);
    s = buf;
  } else if (level == 3) {
    snprintf(buf, sizeof(buf), "x%d.%d.3ci1", 4, pre);
    s = buf;
  }
  (void)level;
  return gen(s);
}

int main() {
  int rb, pre;
  printf("/* zpaqII - generated ZPAQL postprocessor templates.\n");
  printf(" * GENERATED by tools/gen_config.cpp from libzpaq 7.15 (Unlicense).\n");
  printf(" * Do not edit by hand.  See config.c for how they are used. */\n");
  printf("#include \"zq_internal.h\"\n\n");

  /* Level 1: 8 r-bit values x 2 e8e9 variants */
  printf("/* level 1 (variable length LZ77): [e8e9][rb] */\n");
  printf("const char *const zq_tpl_l1[2][8] = {\n");
  for (pre = 0; pre < 2; ++pre) {
    printf("  {\n");
    for (rb = 0; rb < 8; ++rb) {
      char method[128];
      /* block size 4+rb drives the r-bits; pre 1 or 5 selects e8e9 */
      snprintf(method, sizeof(method), "x%d.%d.5.0.3.22", 4 + rb, pre ? 5 : 1);
      std::string cfg = gen(method);
      printf("    ");
      emit_str(pcomp_part(cfg).c_str());
      printf(",\n");
    }
    printf("  },\n");
  }
  printf("};\n\n");

  /* Level 2: [e8e9] */
  printf("/* level 2 (byte-aligned LZ77): [e8e9] */\n");
  printf("const char *const zq_tpl_l2[2] = {\n");
  for (pre = 0; pre < 2; ++pre) {
    std::string cfg = with_blocksize(2, pre ? 6 : 2, 0);
    printf("  ");
    emit_str(pcomp_part(cfg).c_str());
    printf(",\n");
  }
  printf("};\n\n");

  /* Level 3: [e8e9][small block] */
  printf("/* level 3 (BWT): [e8e9][blocksize<=16MB] */\n");
  printf("const char *const zq_tpl_l3[2][2] = {\n");
  for (pre = 0; pre < 2; ++pre) {
    int small;
    printf("  {\n");
    for (small = 0; small < 2; ++small) {
      char method[128];
      snprintf(method, sizeof(method), "x%d.%d.3ci1", small ? 4 : 5, pre ? 7 : 3);
      std::string cfg = gen(method);
      printf("    ");
      emit_str(pcomp_part(cfg).c_str());
      printf(",\n");
    }
    printf("  },\n");
  }
  printf("};\n\n");

  /* Level 0: [e8e9] (one of them is just "end\n") */
  printf("/* level 0 (store / e8e9 only): [e8e9] */\n");
  printf("const char *const zq_tpl_l0[2] = {\n");
  for (pre = 0; pre < 2; ++pre) {
    char method[64];
    snprintf(method, sizeof(method), "x4.%d.0ci1", pre ? 4 : 0);
    std::string cfg = gen(method);
    printf("  ");
    emit_str(pcomp_part(cfg).c_str());
    printf(",\n");
  }
  printf("};\n\n");

  /* Level 2 HCOMP prologue: [e8e9] */
  printf("/* level 2 HCOMP prologue (lz77 parse state in R1, R2): [e8e9] */\n");
  printf("const char *const zq_tpl_hcomp_l2[2] = {\n");
  for (pre = 0; pre < 2; ++pre) {
    std::string cfg = with_blocksize(2, pre ? 6 : 2, 0);
    printf("  ");
    emit_str(hcomp_part(cfg).c_str());
    printf(",\n");
  }
  printf("};\n");
  return 0;
}
